public sealed interface PaymentResult permits Captured, Pending, Declined {}
public record Captured(String txId, long amountCents) implements PaymentResult {}
public record Pending(int retrySeconds) implements PaymentResult {}
public record Declined(String reason) implements PaymentResult {}

public String describe(PaymentResult result) {
    return switch (result) {
        case Captured(var tx, var cents) when cents > 100_000 -> "High-value OK: " + tx;
        case Captured(var tx, _) -> "Captured: " + tx;
        case Pending(var sec) -> "Retry in " + sec + "s";
        case Declined(var reason) -> "Failed: " + reason;
    }; // Exhaustive: no default branch needed!
}
